Set OrdSelectSnap=##class(EnsLib.SQL.Snapshot).%New() Set OrdSelectSnap.MaxRowsToGet=-1 $$$TRACE("Order id before select "_pRequest.OrderId) Set tOrdSelectQuery="SELECT ORDERID,TESTID FROM POST.FOURMEDICAORDER WHERE ORDERID = ? AND TESTID = ?"
Set tSCSelect = ..Adapter.ExecuteQuery(.OrdSelectSnap,tOrdSelectQuery,pRequest.OrderId,pRequest.TestId) $$$TRACE("Order id select status "_tSCSelect)
Set RetOrdId = "" Set RetTestId = "" If $$$ISOK(tSCSelect) { If OrdSelectSnap.Next() { Set RetOrdId = OrdSelectSnap.GetData(1) Set RetTestId = OrdSelectSnap.GetData(2) } } else { $$$TRACE("Error in executing Select OrderId query") Quit tSCSelect } $$$TRACE("Ret ord id and "_RetOrdId_" inbound orderid "_pRequest.OrderId_"RetTestid "_RetTestId)
