Set tSCIDSelect = ..Adapter.ExecuteQuery(.OrdIdSnap,tOrdIdSelectQuery) $$$TRACE("id select status "_tSCIDSelect)
Set RetId = "" If $$$ISOK(tSCIDSelect) { If OrdIdSnap.Next() { Set RetId = OrdIdSnap.GetData(1) } } else { $$$TRACE("Error in executing Select top ID query") Quit tSCIDSelect }
