If (RetOrdId'=pRequest.OrderId) { $$$TRACE("inside if of RetOrdId'=pRequest.OrderId") //Insert the data Set tOrdInsertQuery="insert into post.fourmedicaorder (Id,patientid, firstname, middlename, lastname, dob, sex, orderid, orderdate, physicianname,serviceddate, serviced, active, testid) "_ "values(?,?,?,?,?,?,?,?,?,?,?,?,?,?)"
