Set dob = $Replace($Zdate($ZdateH(pRequest.PatientDOB,8),2)," ","-") Set ordDate = $Replace($Zdate($ZdateH($Extract(pRequest.OrderDate,1,8),8),2)," ","-")
Set:pRequest.ServicedDate'="" servicedDate = $Replace($Zdate($ZdateH($Extract(pRequest.ServicedDate,1,8),8),2)," ","-")
;Set tSC =..Adapter.ExecuteQuery(.OrdInsertSnap,tOrdInsertQuery,"",pRequest.PatientId,pRequest.PatientFirstName,pRequest.PatientMidldleName,pRequest.PatientLastName,pRequest.PatientDOB,pRequest.PatientGender,pRequest.OrderId,$SYSTEM.SQL.TODATE(OrdDate,"yyyy/mm/dd"),pRequest.PhysicianName,$SYSTEM.SQL.TODATE(ServicedDate,"yyyy/mm/dd"),pRequest.Serviced)
//set up multidimensional array of parameters set par(1)=$INCREMENT(RetId) set par(2)=pRequest.PatientId set par(3)=pRequest.PatientFirstName set par(4)= pRequest.PatientMidldleName set par(5)=pRequest.PatientLastName set par(6)= dob set par(7)=pRequest.PatientGender set par(8)=pRequest.OrderId set par(9)= ordDate // _" 11:45"
