Quit:$$$ISERR(tSC) tSC
}
;$$$TRACE("date diff serviced date "_$Zdate($ZdateH($Extract(pRequest.ServicedDate,1,8),8),3)_" curr date "_$ZDATE($HOROLOG,3)) If (pRequest.ServicedDate'="") { If (($System.SQL.DATEDIFF("dd",$ZDATE($HOROLOG,3),$Zdate($ZdateH($Extract(pRequest.ServicedDate,1,8),8),3))<=0)) { //update the Post db flag $$$TRACE("Inside serviced date update") Set ServicedDate = $Replace($Zdate($ZdateH($Extract(pRequest.ServicedDate,1,8),8),2)," ","-")
